#include "GunyahSecurityInit.hpp"
#include "GunyahAmfi.hpp"
#include "GunyahEntitlementBridge.hpp"
#include "GunyahSignaturePolicy.hpp"
#include <libkern/libkern.h>
extern "C" {
#include <pexpert/pexpert.h>
#include <sys/errno.h>
}

/* Generated by tools/make-trust-module-source.py; integrity is the policy's
 * pinned SHA256, not the origin of these bytes.
 */
extern "C" const uint8_t gunyah_os_trust_module[];
extern "C" const size_t gunyah_os_trust_module_size;

static GunyahSignaturePolicy *policy;

extern "C" void gunyah_security_init(void)
{
    unsigned enabled = 0;
    PE_parse_boot_argn("gunyah-iphone-trust", &enabled, sizeof(enabled));
    if (enabled != 1) return;
    policy = GunyahSignaturePolicy::withOSTrustCache(gunyah_os_trust_module, gunyah_os_trust_module_size);
    if (!policy) {
        printf("GUNYAH-XNU: pinned iPhone trust module rejected; no entitlement provider\n");
        return;
    }
    amfi_interface_register(gunyah_amfi_interface());
    printf("GUNYAH-XNU: diagnostic entitlement provider registered\n");
}

extern "C" int gunyah_security_bind(struct cs_blob *blob)
{
    return policy ? gunyah_bind_entitlements(policy, blob) : ENOTSUP;
}
